document.addEventListener("DOMContentLoaded",(()=>{const e=new Map;$(document).on("select2:open",(t=>{if(!1===t.target.classList.value.includes("expandOnFocus"))return;const i=t.target,n=$(i).next(".select2-container");if(n.length){if(!e.has(i.id)){const t=n.find(".select2-selection").outerHeight();e.set(i.id,t)}n.css({height:"auto","min-height":"75px"}),n.find(".select2-selection--multiple").css({height:"auto","min-height":"75px","max-height":"150","overflow-y":"auto"}),n.find(".select2-selection--single").css({height:"auto","min-height":"38px"})}})),$(document).on("select2:close",(t=>{if(!1===t.target.classList.value.includes("expandOnFocus"))return;const i=t.target,n=$(i).next(".select2-container");if(n.length){const t=e.get(i.id)||"38px";n.css({height:t,"min-height":""}),n.find(".select2-selection--multiple").css({height:t,"min-height":"","max-height":"","overflow-y":""}),n.find(".select2-selection--single").css({height:t,"min-height":""})}}))}));
